import itertools as it, numpy as np, time, pickle, os
names='abcdefghzw'
ss='bdfhz adfhz acfhz acehz acegz bcegz bdegz bdfgz bdehw bcfhw bcfgw bcehw adfgw adehw adegw acfgw'.split()
G=np.array([[int(c in s) for c in names] for s in ss],dtype=np.int16)
def maxantichain(A):
 A=np.unique(A,axis=0)
 # descending sum so no later point can dominate earlier point
 A=A[np.argsort(-A.sum(axis=1))]
 keep=[]
 for a in A:
  if not keep or not np.any(np.all(np.array(keep)>=a,axis=1)): keep.append(a)
 return np.array(keep)
def corners(gs,k):
 C=np.full((1,10),k,dtype=np.int16)
 for j,g in enumerate(gs):
  hit=np.all(C>=g,axis=1)
  if not hit.any(): continue
  out=[C[~hit]]
  for i in np.where(g>0)[0]:
   a=C[hit].copy();a[:,i]=g[i]-1;out.append(a)
  C=maxantichain(np.concatenate(out))
 return C
P=np.zeros((1,10),dtype=np.int16)
for k in range(1,5):
 t=time.time()
 P=np.unique((P[:,None,:]+G[None,:,:]).reshape(-1,10),axis=0)
 fn=f'corners{k}.pkl'
 if os.path.exists(fn): C=pickle.load(open(fn,'rb'))
 else:
  C=corners(P,k);pickle.dump(C,open(fn,'wb'))
 primes=sorted(set(''.join(names[i] for i in range(10) if c[i]<k) for c in C),key=lambda x:(len(x),x))
 print(k,len(P),len(C),time.time()-t,primes,flush=True)

